<template>
  <section class="publicationWorkspace">
    <header class="publicationHeader"><div><h2>{{ episode.title }}</h2><p>预览与导出 · {{ episode.productionMode === 'direct' ? '整页直出' : '分格拼页' }} · {{ ready ? '图片已齐全' : '尚有图片待完成' }}</p></div><button @click="emit('edit')">返回修改{{ episode.productionMode === 'direct' ? '画面' : '气泡与排版' }}</button></header>
    <div class="publicationGrid">
      <section class="finishedPages" aria-label="成品预览"><div class="previewToolbar"><button :disabled="selectedPage === 0" @click="selectedPage--" aria-label="上一页">←</button><label>当前页<select v-model.number="selectedPage" :disabled="!previewUrls.length"><option v-for="(_,index) in previewUrls" :key="index" :value="index">{{ index + 1 }} / {{ previewUrls.length }}</option></select></label><button :disabled="selectedPage >= previewUrls.length-1" @click="selectedPage++" aria-label="下一页">→</button><button @click="emit('refresh')">刷新预览</button><button :disabled="!previewUrls.length" @click="emit('full')">放大查看</button></div><p v-if="previewMessage" class="previewMessage" role="status">{{ previewMessage }}</p><button v-if="previewUrls[selectedPage]" class="pageImage" @click="emit('full')"><img :src="previewUrls[selectedPage]" :alt="`成品第 ${selectedPage+1} 页，点击放大`" /></button><div v-else class="previewEmpty">{{ previewMessage || '正在合成预览；尚未配图的画格会显示占位图。' }}</div><p class="pageCaption">{{ episode.productionMode === 'direct' ? '原图导出，图中文字需要重绘修改。' : '1080 × 1440 PNG · 导出包含当前气泡与字幕。' }}</p></section>
      <aside class="publishTools">
        <section class="exportTools"><div class="sectionHeading"><h3>带走作品</h3><span>{{ episode.productionMode === 'direct' ? episode.directPages.filter(page => page.image).length : episode.panels.filter(panel => panel.image).length }} / {{ episode.productionMode === 'direct' ? episode.directPages.length : episode.panels.length }} {{ episode.productionMode === 'direct' ? '页' : '格' }}</span></div><div class="exportButtons"><button class="primary" :disabled="!ready" @click="emit('images')">导出图片</button><button :disabled="!ready" @click="emit('package')">完整发布包 ZIP</button></div><p v-if="!ready" class="helper">补齐缺失图片后即可导出，无需审批。</p><p v-else class="helper">发布包包含图片、文案、来源记录与作品数据。</p><label>发布包封面<select :value="episode.coverPage ?? 0" @change="episode.coverPage = Number(($event.target as HTMLSelectElement).value)"><option v-for="(_,index) in previewUrls" :key="index" :value="index">使用第 {{ index+1 }} 页</option></select></label><small>复用现有漫画页，不额外生成图片。</small></section>
        <section class="postEditor"><div class="sectionHeading"><h3>配套发布文案</h3><span>可直接编辑</span></div><div class="postControls"><label>语气<select v-model="episode.postStyle"><option v-for="tone in ['简单有梗','emo','误会有梗','温柔治愈','轻松科普']" :key="tone">{{ tone }}</option></select></label><button @click="emit('generatePost')">生成候选</button></div><label class="visuallyHidden" for="publicationText">发布正文</label><textarea id="publicationText" v-model="episode.postText" rows="8" placeholder="写下标题、正文与话题标签…" /><small>生成候选不会覆盖这段正文；选定语气后需主动点击生成。</small><div v-if="episode.postCandidate" class="postCandidate"><strong>新候选 · 采用前可修改</strong><textarea v-model="episode.postCandidate" rows="6" maxlength="1200" aria-label="发布文案候选" /><div><button class="primary" @click="episode.postText = episode.postCandidate; episode.postCandidate = ''; emit('save')">采用候选</button><button @click="episode.postCandidate = ''; emit('save')">放弃</button></div></div></section>
        <details class="sourceReview"><summary>说明与来源 · 仅供自审</summary><p>参考：{{ episode.topic.url || episode.topic.source }}{{ episode.researchPackId ? '；另有专题素材包' : '' }}</p><label><input v-model="episode.includeAiDisclosure" type="checkbox" />正文加入 AI 辅助说明</label><label><input v-model="episode.includeReferences" type="checkbox" />正文加入来源</label><pre v-if="episode.includeAiDisclosure || episode.includeReferences">{{ publicationText(episode) }}</pre></details>
        <details class="publicationRecord"><summary>发布与记录</summary><p>导出后在平台自行发布，软件不会自动发帖。</p><a href="https://creator.xiaohongshu.com/" target="_blank" rel="noopener noreferrer">打开小红书创作中心 ↗</a><label>发布后的作品链接<input v-model="episode.publishedUrl" type="url" /></label><button @click="emit('save')">保存发布记录</button></details>
      </aside>
    </div>
  </section>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { productionReady, publicationText, type Episode } from './model';
const props=defineProps<{episode:Episode;previewUrls:string[];previewMessage:string}>();
const emit=defineEmits<{edit:[];refresh:[];full:[];images:[];package:[];generatePost:[];save:[]}>();
const selectedPage=ref(0);
const ready=computed(()=>productionReady(props.episode));
watch(()=>props.previewUrls.length,length=>{if(length)selectedPage.value=Math.min(selectedPage.value,length-1);});
</script>
<style scoped>
