:var(--studioAccent); color:white; border-color:var(--studioAccent); }button:focus-visible { outline:2px solid var(--studioAccent); outline-offset:3px; }label { display:grid; gap:7px; font-size:12px; margin:10px 0; }.postControls { display:flex; gap:10px; align-items:end; margin-bottom:10px; }.postControls label { flex:1; margin:0; }textarea,input[type=url] { width:100%; border:1px solid var(--studioLine); border-radius:7px; padding:12px; background:var(--studioPaper); line-height:1.7; resize:vertical; }.postCandidate { padding-top:16px; margin-top:16px; border-top:1px solid var(--studioLine); }.postCandidate textarea { margin:10px 0; }.postCandidate button { margin-right:8px; }summary { cursor:pointer; font-size:13px; }.sourceReview label { display:flex; align-items:center; }.sourceReview p,.publicationRecord p { font-size:12px; line-height:1.7; overflow-wrap:anywhere; }pre { white-space:pre-wrap; overflow-wrap:anywhere; font-size:12px; }.previewEmpty { padding:100px 25px; text-align:center; color:var(--studioMuted); }.previewMessage { padding:12px; font-size:13px; }.visuallyHidden { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); }@media(max-width:1050px){.publicationGrid { grid-template-columns:1fr; }.finishedPages { position:static; }.publishTools { grid-template-columns:repeat(2,minmax(0,1fr)); }.postEditor { grid-column:2; grid-row:1 / span 3; }}@media(max-width:700px){.publicationHeader { align-items:start; flex-direction:column; }.publishTools { grid-template-columns:1fr; }.postEditor { grid-column:1; grid-row:auto; }}
</style>
